   113  static flb_sds_t flb_msgpack_gelf_value(flb_sds_t *s, int quote,
   114                                          const char *val, int val_len)
   115  {
   116      flb_sds_t tmp;
   117
   118      if (quote == FLB_TRUE) {
   119          tmp = flb_sds_cat(*s, "\"", 1);
   120          if (tmp == NULL) {
   121              return NULL;
   122          }
   123          *s = tmp;
   124
   125          if (val_len > 0) {
   126              tmp = flb_sds_cat_utf8(s, val, val_len);
   127              if (tmp == NULL) {
   128                  return NULL;
   129              }
   130              *s = tmp;
   131          }
   132
   133          tmp = flb_sds_cat(*s, "\"", 1);
   134          if (tmp == NULL) {
   135              return NULL;
   136          }
   137          *s = tmp;
   138      }
   139      else {
   140          tmp = flb_sds_cat(*s, val, val_len);
   141          if (tmp == NULL) {
   142              return NULL;
   143          }
   144          *s = tmp;
   145      }
   146
   147      return *s;
   148  }
