   150  static flb_sds_t flb_msgpack_gelf_value_ext(flb_sds_t *s, int quote,
   151                                              const char *val, int val_len)
   152  {
   153      static const char int2hex[] = "0123456789abcdef";
   154      flb_sds_t tmp;
   155
   156      if (quote == FLB_TRUE) {
   157          tmp = flb_sds_cat(*s, "\"", 1);
   158          if (tmp == NULL) {
   159              return NULL;
   160          }
   161          *s = tmp;
   162      }
   163      /* ext body. fortmat is similar to printf(1) */
   164      {
   165          int i;
   166          char temp[5];
   167          for(i=0; i < val_len; i++) {
   168              char c = (char)val[i];
   169              temp[0] = '\\';
   170              temp[1] = 'x';
   171              temp[2] = int2hex[ (unsigned char) ((c & 0xf0) >> 4)];
   172              temp[3] = int2hex[ (unsigned char) (c & 0x0f)];
   173              temp[4] = '\0';
   174              tmp = flb_sds_cat(*s, temp, 4);
   175              if (tmp == NULL) {
   176                  return NULL;
   177              }
   178              *s = tmp;
   179          }
   180      }
   181      if (quote == FLB_TRUE) {
   182          tmp = flb_sds_cat(*s, "\"", 1);
   183          if (tmp == NULL) {
   184              return NULL;
   185          }
   186          *s = tmp;
   187      }
   188
   189      return *s;
   190  }
