   192  static flb_sds_t flb_msgpack_gelf_flatten(flb_sds_t *s, msgpack_object *o,
   193                                            const char *prefix, int prefix_len,
   194                                            int in_array)
   195  {
   196      int i;
   197      int loop;
   198      flb_sds_t tmp;
   199
   200      switch(o->type) {
   201      case MSGPACK_OBJECT_NIL:
   202          tmp = flb_sds_cat(*s, "null", 4);
   203          if (tmp == NULL) {
   204              return NULL;
   205          }
   206          *s = tmp;
   207          break;
   208
   209      case MSGPACK_OBJECT_BOOLEAN:
   210          if (o->via.boolean) {
   211              tmp = flb_msgpack_gelf_value(s, !in_array, "true", 4);
   212          }
   213          else {
   214              tmp = flb_msgpack_gelf_value(s, !in_array, "false", 5);
   215          }
   216          if (tmp == NULL) {
   217              return NULL;
   218          }
   219          *s = tmp;
   220          break;
   221
   222      case MSGPACK_OBJECT_POSITIVE_INTEGER:
   223          tmp = flb_sds_printf(s, "%lu", (unsigned long)o->via.u64);
   224          if (tmp == NULL) {
   225              return NULL;
   226          }
   227          *s = tmp;
   228          break;
   229
   230      case MSGPACK_OBJECT_NEGATIVE_INTEGER:
   231          tmp = flb_sds_printf(s, "%ld", (signed long)o->via.i64);
   232          if (tmp == NULL) {
   233              return NULL;
   234          }
   235          *s = tmp;
   236          break;
   237
   238      case MSGPACK_OBJECT_FLOAT32:
   239      case MSGPACK_OBJECT_FLOAT64:
   240          tmp = flb_sds_printf(s, "%f", o->via.f64);
   241          if (tmp == NULL) {
   242              return NULL;
   243          }
   244          *s = tmp;
   245          break;
   246
   247      case MSGPACK_OBJECT_STR:
   248          tmp = flb_msgpack_gelf_value(s, !in_array,
   249                                       o->via.str.ptr,
   250                                       o->via.str.size);
   251          if (tmp == NULL) {
   252              return NULL;
   253          }
   254          *s = tmp;
   255          break;
   256
   257      case MSGPACK_OBJECT_BIN:
   258          tmp = flb_msgpack_gelf_value(s, !in_array,
   259                                       o->via.bin.ptr,
   260                                       o->via.bin.size);
   261          if (tmp == NULL) {
   262              return NULL;
   263          }
   264          *s = tmp;
   265          break;
   266
   267      case MSGPACK_OBJECT_EXT:
   268          tmp = flb_msgpack_gelf_value_ext(s, !in_array,
   269                                           o->via.ext.ptr,
   270                                           o->via.ext.size);
   271          if (tmp == NULL) {
   272              return NULL;
   273          }
   274          *s = tmp;
   275          break;
   276
   277      case MSGPACK_OBJECT_ARRAY:
   278          loop = o->via.array.size;
   279
   280          if (!in_array) {
   281              tmp = flb_sds_cat(*s, "\"", 1);
   282              if (tmp == NULL) {
   283                  return NULL;
   284              }
   285              *s = tmp;
   286          }
   287          if (loop != 0) {
   288              msgpack_object* p = o->via.array.ptr;
   289              for (i=0; i<loop; i++) {
   290                  if (i > 0) {
   291                       tmp = flb_sds_cat(*s, ", ", 2);
   292                       if (tmp == NULL) {
   293                           return NULL;
   294                       }
   295                       *s = tmp;
   296                  }
   297                  tmp = flb_msgpack_gelf_flatten(s, p+i,
   298                                                 prefix, prefix_len,
   299                                                 FLB_TRUE);
   300                  if (tmp == NULL) {
   301                      return NULL;
   302                  }
   303                  *s = tmp;
   304              }
   305          }
   306
   307          if (!in_array) {
   308              tmp = flb_sds_cat(*s, "\"", 1);
   309              if (tmp == NULL) {
   310                  return NULL;
   311              }
   312              *s = tmp;
   313          }
   314          break;
   315
   316      case MSGPACK_OBJECT_MAP:
   317          loop = o->via.map.size;
   318          if (loop != 0) {
   319              msgpack_object_kv *p = o->via.map.ptr;
   320              for (i = 0; i < loop; i++) {
   321                  msgpack_object *k = &((p+i)->key);
   322                  msgpack_object *v = &((p+i)->val);
   323
   324                  const char *key = k->via.str.ptr;
   325                  int key_len = k->via.str.size;
   326
   327                  if (v->type == MSGPACK_OBJECT_MAP) {
   328                      char *obj_prefix = NULL;
   329                      int obj_prefix_len = 0;
   330
   331                      obj_prefix_len = key_len;
   332                      if (prefix_len > 0) {
   333                          obj_prefix_len += prefix_len + 1;
   334                      }
   335
   336                      obj_prefix = flb_malloc(obj_prefix_len + 1);
   337                      if (obj_prefix == NULL) {
   338                         return NULL;
   339                      }
   340
   341                      if (prefix_len > 0) {
   342                          memcpy(obj_prefix, prefix, prefix_len);
   343                          obj_prefix[prefix_len] = '_';
   344                          memcpy(obj_prefix + prefix_len + 1, key, key_len);
   345                      }
   346                      else {
   347                          memcpy(obj_prefix, key, key_len);
   348                      }
   349                      obj_prefix[obj_prefix_len] = '\0';
   350
   351                      tmp = flb_msgpack_gelf_flatten(s, v,
   352                                                     obj_prefix, obj_prefix_len,
   353                                                     in_array);
   354                      if (tmp == NULL) {
   355                          flb_free(obj_prefix);
   356                          return NULL;
   357                      }
   358                      *s = tmp;
   359
   360                      flb_free(obj_prefix);
   361                  }
   362                  else {
   363                      if (in_array == FLB_TRUE && i > 0) {
   364                          tmp = flb_sds_cat(*s, " ", 1);
   365                          if (tmp == NULL) {
   366                              return NULL;
   367                          }
   368                          *s = tmp;
   369                      }
   370                      if (in_array && prefix_len <= 0) {
   371                          tmp = flb_msgpack_gelf_key(s, in_array,
   372                                                     NULL, 0,
   373                                                     FLB_FALSE,
   374                                                     key, key_len);
   375                      }
   376                      else {
   377                          tmp = flb_msgpack_gelf_key(s, in_array,
   378                                                     prefix, prefix_len,
   379                                                     FLB_TRUE,
   380                                                     key, key_len);
   381                      }
   382                      if (tmp == NULL) {
   383                          return NULL;
   384                      }
   385                      *s = tmp;
   386
   387                      tmp = flb_msgpack_gelf_flatten(s, v, NULL, 0, in_array);
   388                      if (tmp == NULL) {
   389                          return NULL;
   390                      }
   391                      *s = tmp;
   392                  }
   393              }
   394          }
   395          break;
   396
   397      default:
   398          flb_warn("[%s] unknown msgpack type %i", __FUNCTION__, o->type);
   399      }
   400
   401      return *s;
   402  }
