   404  flb_sds_t flb_msgpack_to_gelf(flb_sds_t *s, msgpack_object *o,
   405                                struct flb_time *tm,
   406                                struct flb_gelf_fields *fields)
   407  {
   408      int i;
   409      int loop;
   410      flb_sds_t tmp;
   411
   412      int host_key_found = FLB_FALSE;
   413      int timestamp_key_found = FLB_FALSE;
   414      int level_key_found = FLB_FALSE;
   415      int short_message_key_found = FLB_FALSE;
   416      int full_message_key_found = FLB_FALSE;
   417
   418      char *host_key = NULL;
   419      char *timestamp_key = NULL;
   420      char *level_key = NULL;
   421      char *short_message_key = NULL;
   422      char *full_message_key = NULL;
   423
   424      int host_key_len = 0;
   425      int timestamp_key_len = false;
   426      int level_key_len = 0;
   427      int short_message_key_len = 0;
   428      int full_message_key_len = 0;
   429
   430      if (s == NULL || o == NULL) {
   431          return NULL;
   432      }
   433
   434      if (fields != NULL && fields->host_key != NULL) {
   435          host_key = fields->host_key;
   436          host_key_len = flb_sds_len(fields->host_key);
   437      }
   438      else {
   439          host_key = "host";
   440          host_key_len = 4;
   441      }
   442
   443      if (fields != NULL && fields->timestamp_key != NULL) {
   444          timestamp_key = fields->timestamp_key;
   445          timestamp_key_len = flb_sds_len(fields->timestamp_key);
   446      }
   447      else {
   448          timestamp_key = "timestamp";
   449          timestamp_key_len = 9;
   450      }
   451
   452      if (fields != NULL && fields->level_key != NULL) {
   453          level_key = fields->level_key;
   454          level_key_len = flb_sds_len(fields->level_key);
   455      }
   456      else {
   457          level_key = "level";
   458          level_key_len = 5;
   459      }
   460
   461      if (fields != NULL && fields->short_message_key != NULL) {
   462          short_message_key = fields->short_message_key;
   463          short_message_key_len = flb_sds_len(fields->short_message_key);
   464      }
   465      else {
   466          short_message_key = "short_message";
   467          short_message_key_len = 13;
   468      }
   469
   470      if (fields != NULL && fields->full_message_key != NULL) {
   471          full_message_key = fields->full_message_key;
   472          full_message_key_len = flb_sds_len(fields->full_message_key);
   473      }
   474      else {
   475          full_message_key = "full_message";
   476          full_message_key_len = 12;
   477      }
   478
   479      tmp = flb_sds_cat(*s, "{\"version\":\"1.1\"", 16);
   480      if (tmp == NULL) {
   481          return NULL;
   482      }
   483      *s = tmp;
   484
   485      loop = o->via.map.size;
   486      if (loop != 0) {
   487          msgpack_object_kv *p = o->via.map.ptr;
   488
   489          for (i = 0; i < loop; i++) {
   490              const char *key = NULL;
   491              int key_len;
   492              const char *val = NULL;
   493              int val_len;
   494              int quote = FLB_FALSE;
   495              int custom_key = FLB_FALSE;
   496
   497              msgpack_object *k = &p[i].key;
   498              msgpack_object *v = &p[i].val;
   499              msgpack_object vtmp; // used when converting level value from string to int
   500
   501              if (k->type != MSGPACK_OBJECT_BIN && k->type != MSGPACK_OBJECT_STR) {
   502                  continue;
   503              }
   504
   505              if (k->type == MSGPACK_OBJECT_STR) {
   506                  key = k->via.str.ptr;
   507                  key_len = k->via.str.size;
   508              }
   509              else {
   510                  key = k->via.bin.ptr;
   511                  key_len = k->via.bin.size;
   512              }
   513
   514              if ((key_len == host_key_len) &&
   515                  !strncmp(key, host_key, host_key_len)) {
   516                  if (host_key_found == FLB_TRUE) {
   517                      continue;
   518                  }
   519                  host_key_found = FLB_TRUE;
   520                  key = "host";
   521                  key_len = 4;
   522              }
   523              else if ((key_len == short_message_key_len) &&
   524                       !strncmp(key, short_message_key, short_message_key_len)) {
   525                  if (short_message_key_found == FLB_TRUE) {
   526                      continue;
   527                  }
   528                  short_message_key_found = FLB_TRUE;
   529                  key = "short_message";
   530                  key_len = 13;
   531              }
   532              else if ((key_len == timestamp_key_len) &&
   533                       !strncmp(key, timestamp_key, timestamp_key_len)) {
   534                  if (timestamp_key_found == FLB_TRUE) {
   535                      continue;
   536                  }
   537                  timestamp_key_found = FLB_TRUE;
   538                  key = "timestamp";
   539                  key_len = 9;
   540              }
   541              else if ((key_len == level_key_len) &&
   542                       !strncmp(key, level_key, level_key_len )) {
   543                  if (level_key_found == FLB_TRUE) {
   544                      continue;
   545                  }
   546                  level_key_found = FLB_TRUE;
   547                  key = "level";
   548                  key_len = 5;
   549                  if (v->type == MSGPACK_OBJECT_POSITIVE_INTEGER) {
   550                      if ( v->via.u64 > 7 ) {
   551                          flb_error("[flb_msgpack_to_gelf] level is %" PRIu64 ", "
   552                                    "but should be in 0..7 or a syslog keyword", v->via.u64);
   553                          return NULL;
   554                      }
   555                  }
   556                  else if (v->type == MSGPACK_OBJECT_STR) {
   557                      val     = v->via.str.ptr;
   558                      val_len = v->via.str.size;
   559                      if (val_len == 1 && val[0] >= '0' && val[0] <= '7') {
   560                          v = &vtmp;
   561                          v->type = MSGPACK_OBJECT_POSITIVE_INTEGER;
   562                          v->via.u64 = (uint64_t)(val[0] - '0');
   563                      }
   564                      else {
   565                          int n;
   566                          char* allowed_levels[] = {
   567                              "emerg", "alert", "crit", "err",
   568                              "warning", "notice", "info", "debug",
   569                              NULL
   570                          };
   571                          for (n = 0; allowed_levels[n] != NULL; ++n) {
   572                              if (val_len == strlen(allowed_levels[n]) &&
   573                                  !strncasecmp(val, allowed_levels[n], val_len)) {
   574                                  v = &vtmp;
   575                                  v->type = MSGPACK_OBJECT_POSITIVE_INTEGER;
   576                                  v->via.u64 = (uint64_t)n;
   577                                  break;
   578                              }
   579                          }
   580                          if (allowed_levels[n] == NULL) {
   581                              flb_error("[flb_msgpack_to_gelf] level is '%.*s', "
   582                                        "but should be in 0..7 or a syslog keyword", val_len, val);
   583                              return NULL;
   584                          }
   585                      }
   586                  }
   587              }
   588              else if ((key_len == full_message_key_len) &&
   589                       !strncmp(key, full_message_key, full_message_key_len)) {
   590                  if (full_message_key_found == FLB_TRUE) {
   591                      continue;
   592                  }
   593                  full_message_key_found = FLB_TRUE;
   594                  key = "full_message";
   595                  key_len = 12;
   596              }
   597              else if ((key_len == 2)  && !strncmp(key, "id", 2)) {
   598                  /* _id key not allowed */
   599                  continue;
   600              }
   601              else {
   602                  custom_key = FLB_TRUE;
   603              }
   604
   605              if (v->type == MSGPACK_OBJECT_MAP) {
   606                  char *prefix = NULL;
   607                  int prefix_len = 0;
   608
   609                  prefix_len = key_len + 1;
   610                  prefix = flb_calloc(1, prefix_len + 1);
   611                  if (prefix == NULL) {
   612                      return NULL;
   613                  }
   614
   615                  prefix[0] = '_';
   616                  strncpy(prefix + 1, key, key_len);
   617                  prefix[prefix_len] = '\0';
   618
   619                  tmp = flb_msgpack_gelf_flatten(s, v,
   620                                                 prefix, prefix_len, FLB_FALSE);
   621                  if (tmp == NULL) {
   622                      flb_free(prefix);
   623                      return NULL;
   624                  }
   625                  *s = tmp;
   626                  flb_free(prefix);
   627
   628              }
   629              else if (v->type == MSGPACK_OBJECT_ARRAY) {
   630                  if (custom_key == FLB_TRUE) {
   631                      tmp = flb_msgpack_gelf_key(s, FLB_FALSE, "_", 1, FLB_FALSE,
   632                                               key, key_len);
   633                  }
   634                  else {
   635                      tmp = flb_msgpack_gelf_key(s, FLB_FALSE, NULL, 0, FLB_FALSE,
   636                                               key, key_len);
   637                  }
   638                  if (tmp == NULL) {
   639                      return NULL;
   640                  }
   641                  *s = tmp;
   642
   643                  tmp = flb_msgpack_gelf_flatten(s, v, NULL, 0, FLB_FALSE);
   644                  if (tmp == NULL) {
   645                      return NULL;
   646                  }
   647                  *s = tmp;
   648              }
   649              else {
   650                  char temp[48] = {0};
   651                  if (v->type == MSGPACK_OBJECT_NIL) {
   652                      val = "null";
   653                      val_len = 4;
   654                      continue;
   655                  }
   656                  else if (v->type == MSGPACK_OBJECT_BOOLEAN) {
   657                      quote   = FLB_TRUE;
   658                      val = v->via.boolean ? "true" : "false";
   659                      val_len = v->via.boolean ? 4 : 5;
   660                  }
   661                  else if (v->type == MSGPACK_OBJECT_POSITIVE_INTEGER) {
   662                      val = temp;
   663                      val_len = snprintf(temp, sizeof(temp) - 1,
   664                                         "%" PRIu64, v->via.u64);
   665                  }
   666                  else if (v->type == MSGPACK_OBJECT_NEGATIVE_INTEGER) {
   667                      val = temp;
   668                      val_len = snprintf(temp, sizeof(temp) - 1,
   669                                         "%" PRId64, v->via.i64);
   670                  }
   671                  else if (v->type == MSGPACK_OBJECT_FLOAT) {
   672                      val = temp;
   673                      val_len = snprintf(temp, sizeof(temp) - 1,
   674                                         "%f", v->via.f64);
   675                  }
   676                  else if (v->type == MSGPACK_OBJECT_STR) {
   677                      /* String value */
   678                      quote   = FLB_TRUE;
   679                      val     = v->via.str.ptr;
   680                      val_len = v->via.str.size;
   681                  }
   682                  else if (v->type == MSGPACK_OBJECT_BIN) {
   683                      /* Bin value */
   684                      quote   = FLB_TRUE;
   685                      val     = v->via.bin.ptr;
   686                      val_len = v->via.bin.size;
   687                  }
   688                  else if (v->type == MSGPACK_OBJECT_EXT) {
   689                      quote   = FLB_TRUE;
   690                      val     = o->via.ext.ptr;
   691                      val_len = o->via.ext.size;
   692                  }
   693
   694                  if (!val || !key) {
   695                    continue;
   696                  }
   697
   698                  if (custom_key == FLB_TRUE) {
   699                      tmp = flb_msgpack_gelf_key(s, FLB_FALSE, "_", 1, FLB_FALSE,
   700                                               key, key_len);
   701                  }
   702                  else {
   703                      tmp = flb_msgpack_gelf_key(s, FLB_FALSE, NULL, 0, FLB_FALSE,
   704                                               key, key_len);
   705                  }
   706                  if (tmp == NULL) {
   707                      return NULL;
   708                  }
   709                  *s = tmp;
   710
   711                  if (v->type == MSGPACK_OBJECT_EXT) {
   712                      tmp = flb_msgpack_gelf_value_ext(s, quote, val, val_len);
   713                  }
   714                  else {
   715                      tmp = flb_msgpack_gelf_value(s, quote, val, val_len);
   716                  }
   717                  if (tmp == NULL) {
   718                      return NULL;
   719                  }
   720                  *s = tmp;
   721              }
   722          }
   723      }
   724
   725      if (timestamp_key_found == FLB_FALSE && tm != NULL) {
   726          tmp = flb_msgpack_gelf_key(s, FLB_FALSE, NULL, 0, FLB_FALSE,
   727                                     "timestamp", 9);
   728          if (tmp == NULL) {
   729              return NULL;
   730          }
   731          *s = tmp;
   732
   733          tmp = flb_sds_printf(s, "%f", flb_time_to_double(tm));
   734          if (tmp == NULL) {
   735              return NULL;
   736          }
   737          *s = tmp;
   738      }
   739
   740      if (short_message_key_found == FLB_FALSE) {
   741          flb_error("[flb_msgpack_to_gelf] missing short_message key");
   742          return NULL;
   743      }
   744
   745      tmp = flb_sds_cat(*s, "}", 1);
   746      if (tmp == NULL) {
   747          return NULL;
   748      }
   749      *s = tmp;
   750
   751      return *s;
   752  }
   753
   754  flb_sds_t flb_msgpack_raw_to_gelf(char *buf, size_t buf_size,
   755     struct flb_time *tm, struct flb_gelf_fields *fields)
   756  {
   757      int ret;
   758      size_t off = 0;
   759      size_t gelf_size;
   760      msgpack_unpacked result;
   761      flb_sds_t s;
   762      flb_sds_t tmp;
   763
   764      if (!buf || buf_size <= 0) {
   765          return NULL;
   766      }
   767
   768      msgpack_unpacked_init(&result);
   769      ret = msgpack_unpack_next(&result, buf, buf_size, &off);
   770      if (ret != MSGPACK_UNPACK_SUCCESS) {
   771          return NULL;
   772      }
   773
   774      gelf_size = (buf_size * 1.3);
   775      s = flb_sds_create_size(gelf_size);
   776      if (s == NULL) {
   777          msgpack_unpacked_destroy(&result);
   778          return NULL;
   779      }
   780
   781      tmp = flb_msgpack_to_gelf(&s, &result.data, tm, fields);
   782      if (tmp == NULL) {
   783          flb_sds_destroy(s);
   784          msgpack_unpacked_destroy(&result);
   785          return NULL;
   786      }
   787      s = tmp;
   788
   789      msgpack_unpacked_destroy(&result);
   790
   791      return s;
   792  }
